package com.rainbowcrabassistant;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("rainbowcrabassistant")
public interface RainbowCrabConfig extends Config
{
	@ConfigItem(
		position = 0,
		keyName = "overlayEnabled",
		name = "Enable overlay",
		description = "Master switch for the trap highlight overlay"
	)
	default boolean overlayEnabled()
	{
		return true;
	}

	@ConfigItem(
		position = 1,
		keyName = "highlightWaiting",
		name = "Highlight waiting traps",
		description = "Highlight traps that are baited and waiting for a crab"
	)
	default boolean highlightWaiting()
	{
		return true;
	}

	@ConfigItem(
		position = 2,
		keyName = "showCountdown",
		name = "Show countdown",
		description = "Show the estimated time remaining above a baited trap"
	)
	default boolean showCountdown()
	{
		return true;
	}

	@ConfigItem(
		position = 3,
		keyName = "timerDisplay",
		name = "Countdown style",
		description = "How the countdown on a baited trap is shown: a whole-tick number, a decimal seconds number, or the same shrinking pie used by RuneLite's built-in Hunter plugin for regular traps"
	)
	default RainbowCrabTimerDisplay timerDisplay()
	{
		return RainbowCrabTimerDisplay.SECONDS;
	}

	@ConfigItem(
		position = 4,
		keyName = "waitingColor",
		name = "Waiting colour",
		description = "Highlight colour for a trap that is baited and waiting for a crab"
	)
	default Color waitingColor()
	{
		return new Color(255, 255, 0, 100);
	}

	@ConfigItem(
		position = 5,
		keyName = "highlightReady",
		name = "Highlight ready traps",
		description = "Highlight traps that have caught a crab and are ready to loot"
	)
	default boolean highlightReady()
	{
		return true;
	}

	@ConfigItem(
		position = 6,
		keyName = "showReadyText",
		name = "Show text",
		description = "Show the ready-text label (set below) above a trap that's ready to loot"
	)
	default boolean showReadyText()
	{
		return true;
	}

	@ConfigItem(
		position = 7,
		keyName = "readyText",
		name = "Ready text",
		description = "The label shown above a trap that's ready to loot"
	)
	default String readyText()
	{
		return "READY";
	}

	@ConfigItem(
		position = 8,
		keyName = "readyColor",
		name = "Colour",
		description = "Highlight colour for a trap that has caught a crab and is ready to loot"
	)
	default Color readyColor()
	{
		return new Color(0, 255, 0, 100);
	}

	@ConfigItem(
		position = 9,
		keyName = "showEmptyOutline",
		name = "Highlight empty traps",
		description = "Show a subtle grey outline on empty, unbaited traps"
	)
	default boolean showEmptyOutline()
	{
		return false;
	}

	@ConfigItem(
		position = 10,
		keyName = "highlightOpacity",
		name = "Highlight opacity",
		description = "Opacity of the trap fill highlight (the colour swatches above set the base colour; this scales its alpha)"
	)
	@Range(min = 0, max = 255)
	default int highlightOpacity()
	{
		return 100;
	}

	@ConfigItem(
		position = 11,
		keyName = "tickOffset",
		name = "Timer offset (ticks)",
		description = "Advanced: shift the countdown by this many game ticks if it consistently reads early/late for you. Negative extends the displayed countdown, positive shortens it. Leave at 0 unless you have a reason to change it."
	)
	@Range(min = -50, max = 50)
	default int tickOffset()
	{
		return 0;
	}
}

package com.rainbowcrabassistant;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

/**
 * Draws a tile highlight + countdown over each tracked Rainbow Crab trap. Purely
 * observational: reads plugin/client state and paints on top of the scene, nothing else.
 */
public class RainbowCrabOverlay extends Overlay
{
	private final Client client;
	private final RainbowCrabPlugin plugin;
	private final RainbowCrabConfig config;

	@Inject
	private RainbowCrabOverlay(Client client, RainbowCrabPlugin plugin, RainbowCrabConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.overlayEnabled() || plugin.getTraps().isEmpty())
		{
			return null;
		}

		int currentTick = client.getTickCount();

		for (RainbowCrabTrap trap : plugin.getTraps().values())
		{
			TileObject tileObject = trap.getTileObject();
			if (tileObject == null)
			{
				continue;
			}

			switch (trap.getState())
			{
				case READY:
					renderReady(graphics, tileObject);
					break;
				case BAITED:
					renderBaited(graphics, tileObject, trap, currentTick);
					break;
				case EMPTY:
				default:
					renderEmpty(graphics, tileObject);
					break;
			}
		}

		return null;
	}

	private void renderReady(Graphics2D graphics, TileObject tileObject)
	{
		if (!config.highlightReady())
		{
			return;
		}

		String text = config.showReadyText() ? config.readyText() : "";
		OverlayUtil.renderTileOverlay(graphics, tileObject, text, withOpacity(config.readyColor()));
	}

	private void renderBaited(Graphics2D graphics, TileObject tileObject, RainbowCrabTrap trap, int currentTick)
	{
		if (!config.highlightWaiting())
		{
			return;
		}

		// A leading '~' means this trap was already baited when the plugin started
		// tracking it, so the true elapsed time is unknown and this is a conservative
		// estimate (counted from "just baited") rather than exact.
		String prefix = trap.isTimingKnown() ? "" : "~";
		double preciseTicksLeft = computePreciseTicksLeft(trap, currentTick);

		String text = "";
		if (config.showCountdown())
		{
			switch (config.timerDisplay())
			{
				case TICKS:
					int rawTicksLeft = Math.max(0, trap.getReadyTick() - currentTick - config.tickOffset());
					text = prefix + rawTicksLeft;
					break;
				case SECONDS:
					text = prefix + String.format("%.1fs", preciseTicksLeft * 0.6);
					break;
				case CIRCLE:
					// No text - the pie drawn below carries the countdown, matching how
					// RuneLite's built-in Hunter plugin shows its regular trap timers.
					break;
			}
		}

		OverlayUtil.renderTileOverlay(graphics, tileObject, text, withOpacity(config.waitingColor()));

		if (config.showCountdown() && config.timerDisplay() == RainbowCrabTimerDisplay.CIRCLE)
		{
			renderCircleTimer(graphics, tileObject, preciseTicksLeft, trap);
		}
	}

	private void renderEmpty(Graphics2D graphics, TileObject tileObject)
	{
		if (!config.showEmptyOutline())
		{
			return;
		}

		OverlayUtil.renderTileOverlay(graphics, tileObject, "", new Color(160, 160, 160, 60));
	}

	/**
	 * Interpolates smoothly between tick boundaries for display purposes only - the
	 * authoritative remaining-ticks value never changes except on a real GameTick, this
	 * just animates the fractional part between them (matters for SECONDS text and for
	 * the CIRCLE pie; TICKS mode ignores the fraction and shows the raw integer instead).
	 */
	private double computePreciseTicksLeft(RainbowCrabTrap trap, int currentTick)
	{
		int ticksLeft = trap.getReadyTick() - currentTick - config.tickOffset();
		long elapsedMs = System.currentTimeMillis() - plugin.getLastTickTimeMillis();
		double fractionalTick = Math.max(0.0, Math.min(1.0, elapsedMs / 600.0));
		return Math.max(0.0, ticksLeft - fractionalTick);
	}

	/** Same net.runelite.client.ui.overlay.components.ProgressPieComponent the built-in Hunter plugin's TrapOverlay uses. */
	private void renderCircleTimer(Graphics2D graphics, TileObject tileObject, double preciseTicksLeft, RainbowCrabTrap trap)
	{
		Point canvasLoc = tileObject.getCanvasLocation();
		if (canvasLoc == null)
		{
			return;
		}

		RainbowCrabSpecies species = RainbowCrabSpecies.forLocation(trap.getLocation());
		int totalTicks = species != null ? species.getTotalTicks() : 1;
		double progress = totalTicks <= 0 ? 0.0 : Math.max(0.0, Math.min(1.0, preciseTicksLeft / totalTicks));

		ProgressPieComponent pie = new ProgressPieComponent();
		pie.setPosition(canvasLoc);
		pie.setProgress(progress);
		pie.setFill(withOpacity(config.waitingColor()));
		pie.setBorderColor(config.waitingColor());
		pie.render(graphics);
	}

	private Color withOpacity(Color base)
	{
		int alpha = Math.max(0, Math.min(255, config.highlightOpacity()));
		return new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha);
	}
}

package com.rainbowcrabassistant;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Highlights Blue and Rainbow Crab traps (The Great Conch and The Crown Jewel) and shows
 * a tick-accurate countdown until each one is ready to loot.
 * <p>
 * Overlay-only: this plugin never clicks, moves the mouse, or interacts with anything.
 * It only subscribes to game object/tick/varbit events and draws on top of the scene.
 * <p>
 * Class/package names still say "RainbowCrab" internally (kept from when this only
 * covered rainbow crabs) even though the plugin now also covers blue crabs - renaming
 * the config group would silently reset everyone's saved settings, so only the
 * user-visible display name below actually changed.
 */
@Slf4j
@PluginDescriptor(
	name = "Crab Trapping Helper",
	description = "Highlights Blue and Rainbow Crab traps and shows their expected ready timer",
	tags = {"hunter", "crab trapping", "blue crab", "rainbow crab", "traps", "timer", "overlay", "sailing", "crown jewel", "great conch"}
	// enabledByDefault intentionally omitted (defaults to true): the Plugin Hub's
	// automated review rejects enabledByDefault=false as confusing UX for something the
	// user explicitly installed.
	// developerPlugin was removed: PluginManager.java skips any plugin with
	// developerPlugin=true unless the client was launched with --developer-mode, which
	// (per RuneLite.java) is only reachable running from source, never on a normally
	// sideloaded/installed client.
)
public class RainbowCrabPlugin extends Plugin
{
	/*
	 * ------------------------------------------------------------------------------------
	 * Object IDs and the actual bug in an earlier version
	 * ------------------------------------------------------------------------------------
	 * A crab trap hole is ONE persistent GameObject (never despawns/respawns across
	 * empty/baited/full) whose displayed appearance is resolved client-side from a
	 * controlling varbit via the RuneScape "impostor"/multiloc mechanism. That means:
	 *
	 *   - GameObject.getId() always returns the trap's BASE id and never changes.
	 *   - The state-specific ids (documented per-species in RainbowCrabSpecies) are the
	 *     *impostor-resolved* ids, obtained via
	 *     client.getObjectDefinition(baseId).getImpostor().getId() - NOT gameObject.getId().
	 *
	 * An earlier version compared gameObject.getId() directly against the state ids,
	 * which never matched anything (the live id is always one of the base ids, never the
	 * state id), which is why no overlay ever appeared. Confirmed against a live client
	 * screenshot of RuneLite's "Identificator" plugin with "Show game object id" + "Show
	 * game object morph id" enabled: each trap showed a base ID distinct from its "Morph
	 * ID", and the Morph IDs matched the wiki-sourced state ids exactly - confirming
	 * those ids were correct all along, just fetched via the wrong API call.
	 *
	 * This also means state transitions (baited -> full, harvest -> re-bait) do NOT fire
	 * GameObjectSpawned/Despawned at all, since the underlying object never respawns -
	 * only the controlling varbit changes. State is tracked via VarbitChanged, exactly
	 * like RuneLite's own built-in Hunter plugin does for crab traps. The varbit that
	 * controls a given hole isn't hardcoded - it's read directly off that hole's own
	 * ObjectComposition.getVarbitId(), discovered at runtime.
	 *
	 * Per-species object ids, hole coordinates, and tick timings are all in
	 * RainbowCrabSpecies. 58905 ("Crab trap (empty)") is shared across every crab
	 * trapping location and every species, which is why it's checked here directly
	 * rather than being part of any one species' data.
	 */
	static final int OBJECT_EMPTY = 58905;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RainbowCrabOverlay overlay;

	@Inject
	private RainbowCrabConfig config;

	private final Map<WorldPoint, RainbowCrabTrap> traps = new HashMap<>();

	private boolean needsReconciliation;

	/**
	 * Wall-clock time of the most recent GameTick, used only to interpolate a smooth
	 * sub-tick countdown display in the overlay. The underlying timer state (baitedTick /
	 * readyTick) is entirely tick-based; this is display interpolation only and never
	 * feeds back into game logic.
	 */
	private long lastTickTimeMillis = System.currentTimeMillis();

	Map<WorldPoint, RainbowCrabTrap> getTraps()
	{
		return traps;
	}

	long getLastTickTimeMillis()
	{
		return lastTickTimeMillis;
	}

	@Provides
	RainbowCrabConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RainbowCrabConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		traps.clear();
		// The scene may already have traps built and baited from before the plugin was
		// enabled (or from before this login). We can't know when those were baited, so
		// we reconcile on the next tick rather than assuming "just baited" for objects
		// that were actually placed minutes ago.
		needsReconciliation = true;
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		traps.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			traps.clear();
		}
		else if (state == GameState.LOGGED_IN)
		{
			needsReconciliation = true;
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject gameObject = event.getGameObject();
		WorldPoint point = gameObject.getWorldLocation();
		RainbowCrabSpecies species = RainbowCrabSpecies.forLocation(point);
		if (species == null)
		{
			return;
		}

		// First time seeing this hole's object - either it was just built, or we've just
		// walked into render distance / the scene reloaded. Either way we can't tell
		// whether an already-baited state is fresh or old, so treat it cautiously.
		RainbowCrabTrap trap = traps.get(point);
		if (trap == null)
		{
			trap = new RainbowCrabTrap(point, gameObject, resolveControllingVarbit(gameObject));
			traps.put(point, trap);
		}
		else
		{
			trap.setTileObject(gameObject);
			trap.setVarbitId(resolveControllingVarbit(gameObject));
		}

		applyFirstSeenState(trap, resolveMorphedId(gameObject.getId()), client.getTickCount(), species);
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject gameObject = event.getGameObject();
		WorldPoint point = gameObject.getWorldLocation();
		RainbowCrabTrap trap = traps.get(point);

		// Only remove if the despawning object is the one we're currently tracking at
		// this tile. Crab trap holes are permanent and don't respawn on state changes
		// (those are varbit-driven, see the class-level comment), so in practice this
		// only fires when the tile leaves render distance or the scene unloads.
		if (trap != null && trap.getTileObject() == gameObject)
		{
			traps.remove(point);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (traps.isEmpty())
		{
			return;
		}

		int currentTick = client.getTickCount();
		for (RainbowCrabTrap trap : traps.values())
		{
			if (trap.getVarbitId() != event.getVarbitId())
			{
				continue;
			}

			RainbowCrabSpecies species = RainbowCrabSpecies.forLocation(trap.getLocation());
			if (species == null)
			{
				continue;
			}

			applyObservedTransition(trap, resolveMorphedId(trap.getTileObject().getId()), currentTick, species);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		lastTickTimeMillis = System.currentTimeMillis();

		if (needsReconciliation)
		{
			reconcileExistingTraps();
			needsReconciliation = false;
		}
	}

	/**
	 * Resolves a trap hole's actual displayed state. GameObject.getId() only ever
	 * returns the hole's base id - the empty/baited/full appearance is a separate,
	 * varbit-driven "impostor" resolution. See the class-level comment for how this was
	 * confirmed.
	 */
	private int resolveMorphedId(int baseObjectId)
	{
		ObjectComposition composition = client.getObjectDefinition(baseObjectId);
		if (composition == null)
		{
			return baseObjectId;
		}

		ObjectComposition impostor = composition.getImpostor();
		return impostor != null ? impostor.getId() : composition.getId();
	}

	private int resolveControllingVarbit(GameObject gameObject)
	{
		ObjectComposition composition = client.getObjectDefinition(gameObject.getId());
		return composition != null ? composition.getVarbitId() : -1;
	}

	/** Applied when a trap's GameObject is seen for the first time - see onGameObjectSpawned. */
	private void applyFirstSeenState(RainbowCrabTrap trap, int resolvedId, int currentTick, RainbowCrabSpecies species)
	{
		if (resolvedId == species.getBaitedObjectId())
		{
			trap.markBaitedWithUnknownProgress(currentTick, species.getTotalTicks());
		}
		else if (species.isFullObjectId(resolvedId))
		{
			trap.markReady();
		}
		else if (resolvedId == OBJECT_EMPTY)
		{
			trap.markEmpty();
		}
		// else: unrecognised id for this species/hole - leave existing state alone
		// rather than guessing.
	}

	/** Applied on a real, freshly-observed VarbitChanged transition - timing is exact. */
	private void applyObservedTransition(RainbowCrabTrap trap, int resolvedId, int currentTick, RainbowCrabSpecies species)
	{
		if (resolvedId == species.getBaitedObjectId())
		{
			trap.markBaited(currentTick, species.getTotalTicks());
		}
		else if (species.isFullObjectId(resolvedId))
		{
			trap.markReady();
		}
		else if (resolvedId == OBJECT_EMPTY)
		{
			trap.markEmpty();
		}
		// else: unrecognised id - leave existing state alone rather than guessing.
	}

	/**
	 * Scans the currently loaded scene for tracked (blue/rainbow) trap holes that already
	 * exist before this plugin started tracking them (plugin enabled or logged in
	 * mid-session) and seeds the trap map from them, exactly as a fresh
	 * GameObjectSpawned would.
	 */
	private void reconcileExistingTraps()
	{
		// Use the local player's own WorldView (not Client.getScene()/getPlane(), which
		// are deprecated shortcuts for the top-level view only) since Crown Jewel is a
		// boat and may render its deck as a non-top-level instanced view while sailing.
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return;
		}

		WorldView worldView = localPlayer.getWorldView();
		Scene scene = worldView.getScene();
		if (scene == null)
		{
			return;
		}

		Tile[][][] tiles = scene.getTiles();
		int plane = worldView.getPlane();
		int currentTick = client.getTickCount();

		for (Tile[] column : tiles[plane])
		{
			for (Tile tile : column)
			{
				if (tile == null)
				{
					continue;
				}

				for (GameObject gameObject : tile.getGameObjects())
				{
					if (gameObject == null)
					{
						continue;
					}

					WorldPoint point = gameObject.getWorldLocation();
					if (traps.containsKey(point))
					{
						continue;
					}

					RainbowCrabSpecies species = RainbowCrabSpecies.forLocation(point);
					if (species == null)
					{
						continue;
					}

					RainbowCrabTrap trap = new RainbowCrabTrap(point, gameObject, resolveControllingVarbit(gameObject));
					applyFirstSeenState(trap, resolveMorphedId(gameObject.getId()), currentTick, species);
					traps.put(point, trap);
				}
			}
		}
	}
}

package com.rainbowcrabassistant;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;

/**
 * Which crab species a trap hole belongs to, and the location/object-id/timing facts
 * needed to track it. A hole's species never changes (it's fixed by which physical
 * location it's built at), so this is looked up once per hole from its WorldPoint.
 * <p>
 * Object ids are transcribed from the OSRS Wiki's infobox wikitext (id/id1/id2/id3
 * fields) as of 2026-09-02 - see {@link RainbowCrabPlugin}'s class-level comment for how
 * "baited"/"full" ids were confirmed to be impostor-resolved ids, not raw GameObject ids:
 * https://oldschool.runescape.wiki/w/Crab_trap_(baited)  id1=58906 Regular (fish offcuts,
 *   red+blue crabs), id2=58907 Fine (fine fish offcuts, rainbow crabs)
 * https://oldschool.runescape.wiki/w/Crab_trap_(full)    id1=58908 Red, id2=58909 Blue,
 *   id3=58910,58911,58912 Rainbow (3 colour variants)
 * Hole coordinates are transcribed from the ObjectLocLine pin lists on
 * https://oldschool.runescape.wiki/w/Hole_(Crab_trapping) (mapID=0, the main world map,
 * not an instance).
 */
enum RainbowCrabSpecies
{
	/**
	 * https://oldschool.runescape.wiki/w/Crab_trapping table says 15 ticks (9s) from
	 * baited to "crabs walk to trap" - as with rainbow (see RAINBOW's totalTicks comment
	 * below), that describes an earlier moment than the trap actually flipping to full,
	 * not the same thing. Empirically measured: a user tick-counted real blue catches
	 * against this plugin's countdown (initially defaulted to 15 + 13 = 28, using the
	 * same correction found for rainbow) and confirmed it needed exactly 3 more ticks,
	 * i.e. the true figure is 28 + 3 = 31 ticks (18.6s). Object ids (58906 baited, 58909
	 * full) were also confirmed directly against a live client screenshot showing base
	 * ID vs Morph ID for both a set and a ready blue trap, matching this file exactly.
	 */
	BLUE(
		ImmutableSet.<WorldPoint>builder()
			.add(new WorldPoint(3213, 2516, 0))
			.add(new WorldPoint(3210, 2514, 0))
			.add(new WorldPoint(3212, 2512, 0))
			.add(new WorldPoint(3214, 2512, 0))
			.add(new WorldPoint(3216, 2514, 0))
			.add(new WorldPoint(3251, 2435, 0))
			.add(new WorldPoint(3253, 2433, 0))
			.add(new WorldPoint(3253, 2431, 0))
			.add(new WorldPoint(3250, 2432, 0))
			.add(new WorldPoint(3250, 2430, 0))
			.build(),
		58906,
		new int[] {58909},
		31
	),

	/**
	 * Empirically measured: a user tick-counted multiple real catches against this
	 * plugin's countdown and found a tickOffset of exactly -13 landed tick-perfect every
	 * time, i.e. the true baited-to-full gap is 25 (the wiki's figure) + 13 = 38 ticks
	 * (22.8s), not the wiki's 25 (15s) - see the note on BLUE above for why those don't
	 * match.
	 */
	RAINBOW(
		ImmutableSet.of(
			new WorldPoint(1759, 2666, 0),
			new WorldPoint(1757, 2665, 0),
			new WorldPoint(1756, 2663, 0),
			new WorldPoint(1757, 2661, 0),
			new WorldPoint(1759, 2660, 0)
		),
		58907,
		new int[] {58910, 58911, 58912},
		38
	);

	private final Set<WorldPoint> holeLocations;
	private final int baitedObjectId;
	private final int[] fullObjectIds;
	private final int totalTicks;

	RainbowCrabSpecies(Set<WorldPoint> holeLocations, int baitedObjectId, int[] fullObjectIds, int totalTicks)
	{
		this.holeLocations = holeLocations;
		this.baitedObjectId = baitedObjectId;
		this.fullObjectIds = fullObjectIds;
		this.totalTicks = totalTicks;
	}

	int getBaitedObjectId()
	{
		return baitedObjectId;
	}

	boolean isFullObjectId(int id)
	{
		for (int fullId : fullObjectIds)
		{
			if (fullId == id)
			{
				return true;
			}
		}
		return false;
	}

	int getTotalTicks()
	{
		return totalTicks;
	}

	/** Returns the species whose holes include this tile, or null if it's not a tracked hole. */
	static RainbowCrabSpecies forLocation(WorldPoint point)
	{
		for (RainbowCrabSpecies species : values())
		{
			if (species.holeLocations.contains(point))
			{
				return species;
			}
		}
		return null;
	}
}

