package com.rainbowcrabassistant;

import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;

/**
 * Tracks one Rainbow Crab trap hole between the moment it's observed baited and the
 * moment it's looted (or first observed, for holes that were already active when the
 * plugin started).
 */
class RainbowCrabTrap
{
	private final WorldPoint location;
	private TileObject tileObject;
	private int varbitId;
	private RainbowCrabTrapState state;
	private int baitedTick;
	private int readyTick;
	private boolean timingKnown;

	/**
	 * @param varbitId the varbit that controls this specific hole's displayed state
	 * (from {@code ObjectComposition.getVarbitId()}), used to match incoming
	 * {@code VarbitChanged} events back to this trap. State itself starts as EMPTY here;
	 * the caller applies the real initial state right after construction.
	 */
	RainbowCrabTrap(WorldPoint location, TileObject tileObject, int varbitId)
	{
		this.location = location;
		this.tileObject = tileObject;
		this.varbitId = varbitId;
		this.state = RainbowCrabTrapState.EMPTY;
		this.baitedTick = -1;
		this.readyTick = -1;
		this.timingKnown = false;
	}

	WorldPoint getLocation()
	{
		return location;
	}

	TileObject getTileObject()
	{
		return tileObject;
	}

	void setTileObject(TileObject tileObject)
	{
		this.tileObject = tileObject;
	}

	int getVarbitId()
	{
		return varbitId;
	}

	void setVarbitId(int varbitId)
	{
		this.varbitId = varbitId;
	}

	RainbowCrabTrapState getState()
	{
		return state;
	}

	/**
	 * Marks this trap baited (or freshly re-baited after an automatic re-bait). The
	 * ready tick is authoritative only when the trap was observed transitioning from
	 * empty -&gt; baited by this plugin; see {@link #markBaitedWithUnknownProgress(int, int)}
	 * for the startup-reconciliation case.
	 */
	void markBaited(int currentTick, int totalTicks)
	{
		this.state = RainbowCrabTrapState.BAITED;
		this.baitedTick = currentTick;
		this.readyTick = currentTick + totalTicks;
		this.timingKnown = true;
	}

	/**
	 * Used only when a baited trap is first observed (plugin start/login, or a hole's
	 * GameObject entering render distance for the first time) and the actual tick it was
	 * baited on cannot be reconstructed. We optimistically assume it was just baited (full
	 * {@code totalTicks} remaining) rather than pretending to know the true elapsed time -
	 * the countdown will self-correct the moment the trap actually becomes ready, since
	 * that transition is always detected directly off the controlling varbit.
	 */
	void markBaitedWithUnknownProgress(int currentTick, int totalTicks)
	{
		this.state = RainbowCrabTrapState.BAITED;
		this.baitedTick = currentTick;
		this.readyTick = currentTick + totalTicks;
		this.timingKnown = false;
	}

	void markReady()
	{
		this.state = RainbowCrabTrapState.READY;
		this.baitedTick = -1;
		this.readyTick = -1;
		this.timingKnown = true;
	}

	void markEmpty()
	{
		this.state = RainbowCrabTrapState.EMPTY;
		this.baitedTick = -1;
		this.readyTick = -1;
		this.timingKnown = true;
	}

	int getReadyTick()
	{
		return readyTick;
	}

	boolean isTimingKnown()
	{
		return timingKnown;
	}
}

